from format_lecon import Lesson,paras,steps,table,ABBR,D
from html import escape
ABBR.update({'ICHD-3':'troisième édition de la Classification internationale des céphalées','SSC':'Société suisse des céphalées','IMAO':'inhibiteur de la monoamine oxydase','MAO':'monoamine oxydase','ISRS':'inhibiteur sélectif du recaptage de la sérotonine','ISRSN':'inhibiteur sélectif du recaptage de la sérotonine et de la noradrénaline','COX-2':'cyclo-oxygénase de type 2','c.-à-d.':'c’est-à-dire'})
texts={n:(D/'evidence'/f'{n}_frais.txt').read_text().splitlines() for n in ('imigran','algifor')}
def q(n,start):
 found=list(dict.fromkeys(s for s in texts[n] if s.startswith(start)));assert len(found)==1,(n,start,len(found))
 return '<blockquote><p>« '+escape(found[0].removeprefix('·'))+' »</p></blockquote>'
def s(t):return q('imigran',t)
def i(t):return q('algifor',t)
l=Lesson('Migraine avec aura visuelle',9)
sumat=l.subwindow('imigran','Sumatriptan oral : Imigran 50 mg',paras('La notice commune utilise la clé documentaire 51684, également numéro de l’injectable. Le comprimé classique de 50 mg porte le numéro Swissmedic 51685 et le comprimé T celui de 56411. Seule la voie orale adulte est détaillée ici. La présentation classique est sécable, celle marquée T ne l’est pas.',
'Le traitement vise la crise migraineuse diagnostiquée, pas un déficit visuel d’origine encore inconnue. Un triptan n’est pas utilisé pour interrompre une aura isolée. Les signes d’alarme imposent d’abord la filière appropriée.')+
'<h3>Indication et dose</h3>'+s('1 comprimé pelliculé contient 50')+s('Pour le traitement aigu des crises')+s('Imigran ne doit pas être utilisé pour le traitement prophylactique')+s('La dose unique est comprise entre')+s("Les patients qui n'ont pas répondu à la première dose")+s("Si le patient a répondu à la première dose, mais que les symptômes réapparaissent, d'autres doses")+s('Outre les comprimés, aucune autre forme')+paras('Il faut distinguer l’échec initial de la récidive après amélioration. La reprise chiffrée de la notice concerne la seconde situation. Le plafond quotidien est un maximum, pas une dose à atteindre. Ne pas additionner sans plan les comprimés, le spray et l’injectable. Ne pas remplacer de sa propre initiative par un autre triptan dans les mêmes 24 heures.')+
'<h3>Contre-indications et diagnostic</h3>'+paras('Les inhibiteurs de la monoamine oxydase (IMAO) sont une classe de médicaments à vérifier avant le sumatriptan.')+s('Hypersensibilité au principe actif')+s('Imigran ne doit pas être utilisé pour traiter la migraine hémiplégique')+s('cardiopathie ischémique,')+s('Imigran ne doit pas être administré à des patients ayant')+s('Imigran ne doit pas être administré à des patients traités simultanément')+s('Le sumatriptan ne doit pas être administré simultanément')+s("Imigran n'est pas indiqué pour les patients souffrant")+s("Imigran ne doit être utilisé qu'en présence")+s("La présence d'une maladie neurologique potentiellement sérieuse")+paras('La notice emploie des dénominations anciennes, notamment « basilaire » et « ophtalmoplégique ». Elles sont conservées dans la citation sans assimiler une paralysie oculomotrice nouvelle à une aura visuelle typique.')+
'<h3>Âge, reins et foie</h3>'+s("L'efficacité d'Imigran chez l'adolescent a été démontrée")+s("L'expérience chez les patients âgés de plus de 65")+s("Chez l'insuffisant hépatique, la dose de 25")+paras('L’absence d’indication chez l’insuffisant rénal et l’insuffisant hépatique sévère est rappelée dans les contre-indications. Chez l’adolescent, la démonstration d’efficacité de la voie nasale ne valide pas les comprimés adultes. Aucun schéma pédiatrique n’est déduit ici.')+
'<h3>Interactions et tolérance</h3>'+paras('La monoamine oxydase (MAO) est une enzyme ; ses inhibiteurs sont abrégés IMAO. Les inhibiteurs sélectifs du recaptage de la sérotonine (ISRS) et de la sérotonine/noradrénaline (ISRSN) figurent parmi les associations à revoir.')+s('Le sumatriptan peut provoquer une augmentation passagère')+s("Lors de la prise simultanée de triptans et d'autres médicaments")+s("L'administration concomitante de sumatriptan et d'autres triptans")+s('Si des symptômes évoquant une maladie cardiaque ischémique')+paras('Une douleur thoracique suspecte nécessite une évaluation avant toute nouvelle prise. Agitation, fièvre, tremblements, anomalies réflexes ou diarrhée dans une association sérotoninergique demandent un avis urgent. La liste des traitements doit être vérifiée avant prescription.')+
'<h3>Grossesse, allaitement et conduite</h3>'+s('Différents registres de grossesse ont documenté')+s('En raison du passage du sumatriptan dans le lait maternel')+s('Une somnolence, des vertiges, des nausées')+paras('La notice demande de renoncer à l’allaitement pendant les 12 heures suivant l’administration. Cette consigne et l’organisation de l’alimentation du nourrisson sont à discuter avant l’usage. Pendant un trouble visuel, ne pas conduire même si la douleur est peu intense.')+
'<h3>Conservation</h3>'+s('Ne pas conserver les comprimés pelliculés coupés')+paras('Les règles d’une présentation ne se transfèrent pas à une autre. Le nom, le dosage, le caractère sécable et le nombre de prises autorisées doivent figurer clairement sur le plan de traitement.'),(78,))
ibu=l.subwindow('algifor','Ibuprofène : Algifor-L forte 400',paras('Algifor-L forte 400 contient 400 mg d’ibuprofène sous forme de lysinate, Swissmedic 55766. Il s’agit d’un anti-inflammatoire non stéroïdien (AINS). Les comprimés ne sont pas destinés à être partagés pour une demi-dose. Le cadre d’automédication de cette notice ne couvre pas l’évaluation d’un symptôme visuel nouveau.')+
'<h3>Cadre et dose de la présentation</h3>'+i('Algifor-L forte 400, comprimé filmé:')+i('Algifor-L est autorisé en automédication')+i('maux de tête (céphalées);')+i('Adultes et adolescents de plus de 12 ans')+i("Dose simple: 1 comprimé filmé d'Algifor-L forte 400.")+i('Délai entre 2 administrations:')+i("Dose maximale en automédication: 3 comprimés d'Algifor-L forte 400")+i('Sans prescription médicale, Algifor-L est indiqué')+paras('Cette notice donne une dose simple de 400 mg. La fourchette d’une recommandation générale ne permet pas de doubler cette dose en automédication. Le maximum quotidien et la durée maximale sont deux limites distinctes.')+
'<h3>Contre-indications</h3>'+paras('La classification fonctionnelle de la New York Heart Association (NYHA) décrit le retentissement de l’insuffisance cardiaque. Les chiffres romains III et IV de la citation désignent ses classes sévères.')+i('Hypersensibilité au principe actif')+i('Anamnèse de bronchospasme,')+i('Troisième trimestre de la grossesse')+i('Ulcères gastriques')+i('Maladies intestinales inflammatoires')+i('Troubles sévères de la fonction hépatique')+i('Insuffisance rénale sévère')+i('Insuffisance cardiaque sévère')+i('Traitement des douleurs post-opératoires')+
'<h3>Risques et associations</h3>'+i("L'utilisation d'Algifor-L en combinaison")+i("Les patients souffrant d'une forte déshydratation")+i("Il convient d'être prudent pour les patients prenant simultanément des médicaments")+i("En cas de survenue d'hémorragies gastro-intestinales")+paras('Éviter de cumuler plusieurs anti-inflammatoires. Anticoagulants, antiagrégants, corticoïdes et certains antidépresseurs augmentent le risque hémorragique. Diurétiques et traitements agissant sur le système rénine-angiotensine demandent une attention rénale. Revoir aussi lithium, méthotrexate et les autres traitements avant utilisation.',
'Consulter rapidement devant selles noires, vomissement sanglant, réaction allergique, éruption avec atteinte muqueuse ou baisse des urines. Le médicament peut masquer une infection. Une aggravation ne doit pas être traitée par une simple augmentation des doses.')+
'<h3>Grossesse et allaitement</h3>'+i('Pendant les premier et deuxième trimestre')+i("La prise d'AINS à partir de la 20")+i("Il y a lieu d'envisager une surveillance par échographie")+i("L'ibuprofène est contre-indiqué pendant le troisième trimestre")+i('Les AINS passent dans le lait maternel.')+paras('La notice de ce produit déconseille son administration pendant l’allaitement et prévoit une autre alimentation si le traitement est indispensable. Ce texte ne doit pas être remplacé par une affirmation générale sur toute la classe. Une grossesse ou un projet de grossesse exige une réévaluation du plan thérapeutique.')+
'<h3>Âge et usage répété</h3>'+i("L'utilisation et la sécurité d'Algifor-L 200")+i('Chez le patient âgé, les effets indésirables')+i("En cas d'utilisation prolongée d'antalgiques,")+paras('Le produit n’est pas le traitement préventif de la migraine. Des crises répétées ou un recours fréquent aux médicaments imposent de revoir le diagnostic et la prévention avec le médecin.'),(79,))
l.add('La {migraine avec aura visuelle} comporte des symptômes neurologiques transitoires et réversibles. Ils se développent souvent progressivement et peuvent précéder ou accompagner la céphalée. L’expression « migraine ophtalmique » est ambiguë et ne prouve pas une origine oculaire.',paras('L’aura visuelle habituelle relève des voies cérébrales de la vision. Elle peut se manifester par des scintillements, des zigzags ou une zone manquante du champ. Un trouble ressenti à gauche ne signifie pas nécessairement une atteinte du seul œil gauche.',
'La migraine rétinienne est une entité très rare, réellement monoculaire et diagnostiquée après exclusion des autres causes. Une perte d’un seul œil doit donc être évaluée, même si elle régresse. L’aura peut aussi survenir sans mal de tête.'),(12,75,76))
l.add('Le {contexte clinique} associe des crises récidivantes et un retentissement variable. Des crises avec et sans aura peuvent coexister chez une même personne. Les données générales de migraine ne permettent pas de classer ce diagnostic par fréquence suisse parmi les troubles visuels.',paras('L’histoire personnelle et familiale aide à reconnaître un tableau récurrent. Elle ne protège pas contre l’apparition d’une autre maladie. Le caractère nouveau ou différent d’un épisode doit être recherché à chaque évaluation.',
'Le nombre de jours avec céphalée, les jours de prise de médicaments et l’impact sur les activités sont plus utiles au suivi qu’un simple compte de comprimés. Les variations hormonales, le sommeil et le rythme de vie peuvent moduler les crises. Éviter d’attribuer toute plainte au stress.'),(12,72,77))
l.add('La {physiopathologie} implique une modification transitoire de l’activité corticale. Une onde de dépolarisation suivie d’une réduction d’activité est un mécanisme proposé pour l’aura. Le traitement de la céphalée et celui d’un signe neurologique nouveau ne se confondent pas.',paras('La propagation d’une perturbation corticale aide à comprendre l’extension progressive des phénomènes visuels. Ce modèle ne doit pas être réduit à une simple succession de fermeture puis d’ouverture des vaisseaux.',
'Les phénomènes positifs ajoutent une perception, comme un scintillement. Les phénomènes négatifs retirent une partie de la vision. Les deux peuvent coexister, mais leur présence ne suffit pas à exclure une ischémie dans un épisode inhabituel.'),(12,77))
l.add('Les {signes d’alarme} priment sur l’étiquette de migraine connue. Un déficit brutal ou persistant, une perte monoculaire, une faiblesse ou une céphalée en coup de tonnerre nécessite une évaluation urgente. Les durées de classification ne sont jamais un délai à attendre avant de demander de l’aide.',paras('Devant un déficit neurologique nouveau suspect d’accident vasculaire cérébral, activer la filière urgente, notamment le 144 en Suisse. Une régression ne rend pas le symptôme sans importance. Ne pas essayer d’abord un triptan pour établir le diagnostic.',
'Une première aura inhabituelle, une nouvelle présentation après 50 ans, une fièvre, une raideur méningée, un traumatisme, un cancer, une grossesse ou le post-partum modifient le bilan. Un œil rouge douloureux avec baisse visuelle fait aussi rechercher une urgence ophtalmologique.',
'Une personne peut avoir une migraine habituelle et une nouvelle affection simultanément. L’amélioration après antalgique ne distingue pas une céphalée primaire d’une cause secondaire.'),(11,62,72,73,75,78))
l.add('L’{anamnèse} reconstitue l’ordre et la durée de chaque symptôme. Elle recherche ce qui est identique aux épisodes antérieurs et ce qui change. Un dessin du champ visuel et un calendrier peuvent améliorer la description.',steps('Préciser début brutal ou progressif, extension, succession des signes et réversibilité complète.','Distinguer phénomènes lumineux, zone manquante, vision double et baisse d’acuité.','Demander si le trouble persistait en couvrant alternativement chaque œil, sans retarder l’aide urgente.','Noter le lien temporel avec la céphalée et les autres symptômes neurologiques.','Recueillir les jours de céphalée et de médicaments, les traitements efficaces ou mal tolérés et les signes d’alarme.','Rechercher facteurs vasculaires, tabac, contraception, grossesse, comorbidités et interactions.'),(12,72,73,75))
l.add('L’{examen ciblé} comprend l’état général, la pression artérielle et l’examen neurologique. L’examen visuel précise acuité, pupilles, champ et motricité selon les symptômes. Une anomalie persistante oblige à élargir le diagnostic.',paras('Tester chaque œil aide à distinguer une baisse monoculaire d’un déficit homonyme, situé du même côté du champ des deux yeux. Un examen ophtalmologique est indiqué si la plainte ou les signes orientent vers l’œil. Un fond d’œil peut rechercher notamment œdème papillaire ou atteinte rétinienne.',
'L’examen entre crises peut être normal dans une migraine. Cette normalité ne suffit cependant pas à annuler un récit de perte monoculaire ou de déficit focal soudain. Le contexte et la chronologie restent déterminants.'),(70,72,73,75))
l.add('L’{approche syndromique} compare aura, ischémie, épilepsie et causes oculaires. Le début progressif et la succession des symptômes orientent vers l’aura. Ces tendances ne constituent pas une règle absolue de tri.',table(['Tableau','Hypothèse à examiner','Conduite'],[
['Phénomènes visuels progressifs, réversibles, semblables aux crises connues','Aura possible.','Vérifier critères, absence d’alarme et plan de traitement.'],
['Perte monoculaire, même transitoire','Ischémie ou autre cause oculaire ; migraine rétinienne très rare.','Évaluation urgente et exclusion des causes menaçantes.'],
['Déficit brutal, faiblesse, langage nouveau anormal','Accident vasculaire ou autre urgence neurologique.','Filière urgente, pas d’attente de fin d’aura supposée.'],
['Phénomènes très brefs et stéréotypés avec altération de conscience','Crise épileptique possible.','Évaluation neurologique adaptée.'],
['Flashes nouveaux, corps flottants ou rideau','Atteinte vitréorétinienne.','Examen rétinien urgent selon le tableau.']
]),(1,12,70,73,75))
l.add('Le {diagnostic positif} repose sur des crises compatibles et l’exclusion d’une meilleure explication. La troisième édition de la Classification internationale des céphalées, ICHD-3, exige au moins deux crises répondant aux critères. Cette exigence ne justifie pas d’attendre une seconde crise pour explorer un premier épisode inquiétant.',paras('Les symptômes d’aura doivent être entièrement réversibles. La classification générale demande au moins trois caractéristiques parmi les six suivantes. Les durées concernent chaque symptôme, pas forcément la somme de plusieurs symptômes successifs.')+steps('Au moins un symptôme progresse sur 5 minutes ou davantage.','Au moins deux symptômes apparaissent successivement.','Chaque symptôme dure de 5 à 60 minutes.','Au moins un symptôme est unilatéral.','Au moins un symptôme est positif.','Une céphalée accompagne l’aura ou suit dans les 60 minutes.')+paras('L’aura typique comporte des symptômes visuels, sensitifs ou du langage, sans manifestation motrice, rétinienne ou du tronc cérébral. Une aura peut être sans céphalée. Les formes prolongées ou atypiques nécessitent un raisonnement spécialisé et ne sont pas déclarées bénignes sur cette liste seule.'),(12,76))
l.add('Les {examens complémentaires} sont guidés par les atypies et les signes d’alarme. Une migraine typique déjà établie avec examen normal n’impose pas une imagerie répétée de principe. Un premier tableau inhabituel exige une évaluation adaptée.',
'<h3>9.a — Référence diagnostique</h3>'+paras('L’histoire clinique et les critères de classification sont centraux. Il n’existe pas d’analyse sanguine confirmant à elle seule l’aura. Les examens cherchent surtout une autre cause lorsqu’elle est plausible.')+
'<h3>9.b — Première intention</h3>'+paras('Évaluer la gravité, la fonction visuelle et l’examen neurologique. Choisir le circuit d’urgence en cas de déficit nouveau, de céphalée inhabituelle ou de perte monoculaire.')+
'<h3>9.c — Examens dirigés</h3>'+paras('Imagerie cérébrale et vasculaire, explorations ophtalmologiques, analyses ou ponction lombaire répondent à l’hypothèse clinique. Leur ordre dépend notamment d’une suspicion vasculaire, infectieuse ou d’hypertension intracrânienne. Ne pas transformer ce choix en bilan identique pour tous.')+
'<h3>9.d — Seconde intention</h3>'+paras('Revoir le diagnostic si les crises changent, si un déficit persiste ou si le traitement échoue. Le calendrier et les comptes rendus antérieurs permettent une réévaluation documentée. La résistance au traitement n’autorise pas une escalade aveugle.'),(12,70,72,73))
l.add('L’{arbre décisionnel} commence par les urgences. Une fois le diagnostic suffisamment établi, le plan distingue aura, céphalée et prévention. La sécurité du médicament est vérifiée avant chaque changement de stratégie.',steps('Si déficit nouveau brutal ou persistant, faiblesse, perte monoculaire ou céphalée en coup de tonnerre : filière urgente.','Si présentation inhabituelle ou première aura incertaine : avis clinique et examens dirigés, avant de conclure.','Si crise typique connue sans alarme : appliquer le plan personnalisé, se mettre en sécurité et ne pas conduire pendant le trouble visuel.','Traiter la céphalée selon intensité, réponse antérieure et contre-indications ; ne pas utiliser le triptan pour une aura isolée.','Si échec ou récidive : respecter les règles du produit et réévaluer ; ne pas cumuler sans plan.','Si crises fréquentes, handicapantes ou recours répété aux médicaments : discuter prévention et suivi.'),(12,72,73,74,78,79))
l.add('La {prise en charge suisse} vise à réduire le handicap des crises et à limiter leur répétition. Elle associe information, mesures de vie et traitement adapté. Une ordonnance de crise ne remplace pas le bilan d’un symptôme nouveau.',
'<h3>11.A — But</h3>'+paras('Soulager la céphalée, améliorer les activités et éviter le surusage médicamenteux. Les symptômes visuels restent surveillés, avec un plan explicite si leur présentation change.')+
'<h3>11.B — Moyens</h3>'+paras('Un anti-inflammatoire peut convenir à une crise selon le terrain. Présentation suisse documentée : '+ibu+'. Un triptan peut être retenu pour une crise invalidante ou une réponse insuffisante, après vérification des contre-indications : '+sumat+'.',
'La synthèse française propose un anti-inflammatoire au début de l’aura et le triptan au début de la céphalée. La recommandation suisse conseille d’attendre la fin de l’aura avant le triptan. Le plan retenu doit être explicite ; aucun triptan n’est proposé pour supprimer une aura isolée.',
'La recommandation générale suisse évoque une seconde prise en cas d’amélioration insuffisante. Pour Imigran, la notice est plus restrictive : absence de réponse initiale et récidive après réponse sont distinguées. Ici, la règle du produit est conservée.',
'Nausées importantes, contre-indications ou échec peuvent conduire à choisir une autre voie ou un autre médicament avec le médecin. Aucun antiémétique, gépant, traitement de fond ou schéma pédiatrique n’est dosé sans sa propre notice. Les opioïdes ne sont pas une solution de routine à la crise migraineuse.')+
'<h3>11.C — Surveillance</h3>'+paras('Noter réponse, récidive, tolérance et nombre de jours de traitement. Respecter plafonds et intervalles. Rechercher les effets digestifs, rénaux, allergiques ou cardiovasculaires selon le produit. Une nouvelle manifestation neurologique demande une réévaluation, même sous traitement.')+
'<h3>11.D — Pronostic et suivi</h3>'+paras('Une prévention se discute selon fréquence, durée, sévérité, auras gênantes, tolérance et souhaits du patient. Elle ne consiste pas à prendre plus souvent le traitement aigu. Le choix dépend aussi de la grossesse, des comorbidités et des règles de prescription suisses.'),(72,74,78,79))
l.add('La {prévention} combine régularité du rythme de vie et révision des facteurs de risque. Le calendrier aide à détecter un recours excessif aux traitements de crise. La contraception doit être réévaluée en cas de migraine avec aura.',paras('Favoriser sommeil et repas réguliers, hydratation, activité adaptée et stratégies de gestion du stress. Identifier les déclencheurs personnels sans imposer une liste d’interdictions alimentaires ni culpabiliser le patient. Les mesures non médicamenteuses complètent les traitements lorsque ceux-ci sont indiqués.',
'La Société suisse des céphalées recommande de limiter les jours de prise des médicaments aigus et d’expliquer le risque de céphalées par surusage. Un besoin fréquent doit conduire à consulter, sans attendre d’avoir consommé tous les plafonds.',
'Les contraceptifs combinés contenant un œstrogène sont contre-indiqués en cas de migraine avec aura selon la recommandation suisse. Organiser avec le prescripteur une méthode adaptée et une continuité contraceptive. Le tabagisme et les autres facteurs vasculaires doivent aussi être pris en charge.'),(72,77,78,79))
l.add('Les {points clés} distinguent aura cérébrale et perte monoculaire. Une histoire migraineuse ne dispense jamais de rechercher les urgences. La répétition d’un médicament suit sa notice, pas une règle unique appliquée à toute la classe.',paras('Chronologie, réversibilité, examen et contexte font le diagnostic. Une aura sans céphalée existe, mais un épisode nouveau ou atypique ne doit pas être banalisé. Les critères de durée ne sont pas des consignes d’attente.',
'Imigran classique et T diffèrent par la sécabilité. Algifor-L forte 400 reste limité par sa dose simple et ses contre-indications. La grossesse et l’allaitement demandent une lecture du produit précis, et la prévention demande une décision distincte.'),(12,72,75,76,78,79))
l.quiz([
('Question 1 — Une aura visuelle prouve-t-elle une maladie de l’œil ?', 'Non. L’aura habituelle relève des voies visuelles cérébrales. Le terme « migraine ophtalmique » peut être trompeur.'),
('Question 2 — Une perte transitoire d’un seul œil peut-elle être appelée migraine sans bilan ?', 'Non. Il faut exclure les autres causes ; la migraine rétinienne est très rare.'),
('Question 3 — Faut-il attendre 60 minutes devant un déficit brutal nouveau ?', 'Non. Les critères de durée ne sont pas un délai de sécurité. Il faut organiser l’évaluation urgente.'),
('Question 4 — L’aura peut-elle exister sans céphalée ?', 'Oui, mais une première présentation ou une atypie demande une évaluation appropriée.'),
('Question 5 — Les six caractéristiques ICHD-3 doivent-elles toutes être présentes ?', 'Non. La classification générale exige au moins trois de ces six caractéristiques, avec les autres critères requis.'),
('Question 6 — La durée de 5 à 60 minutes concerne-t-elle nécessairement toute la succession des symptômes ?', 'Non. Elle concerne chaque symptôme individuel ; plusieurs symptômes peuvent se succéder.'),
('Question 7 — Une faiblesse motrice appartient-elle à l’aura typique visuelle, sensitive ou du langage ?', 'Non. Elle change la classification et surtout le diagnostic différentiel urgent si elle est nouvelle.'),
('Question 8 — Un triptan est-il destiné à interrompre une aura isolée ?', 'Non. Le plan vise la céphalée migraineuse et respecte le moment de prise convenu.'),
('Question 9 — Peut-on répéter Imigran pour la même crise sans réponse à la première dose ?', 'Non selon la notice. La répétition décrite concerne la récidive après une réponse initiale.'),
('Question 10 — Tous les comprimés Imigran 50 mg peuvent-ils être coupés ?', 'Non. Le comprimé classique est sécable ; le comprimé T ne l’est pas.'),
('Question 11 — La dose maximale quotidienne d’Algifor permet-elle de doubler sa dose simple ?', 'Non. Chaque limite doit être respectée : dose simple, intervalle, maximum quotidien et durée.'),
('Question 12 — Une céphalée soulagée par un médicament exclut-elle une cause secondaire ?', 'Non. La réponse antalgique ne permet pas cette distinction.'),
('Question 13 — Une contraception combinée avec œstrogène est-elle banalisée en cas d’aura ?', 'Non. Elle est contre-indiquée selon la recommandation suisse ; une alternative et la continuité contraceptive doivent être organisées.'),
('Question 14 — Une prévention consiste-t-elle à multiplier les prises du médicament de crise ?', 'Non. Le surusage peut aggraver les céphalées. La prévention repose sur un projet distinct et suivi.')
],(12,72,73,74,75,76,78,79))
l.write()
